import { defineRouteMiddleware, type StarlightRouteData } from "@astrojs/starlight/route-data";

const indexPagePath = /^\/release-notes\/(?:\d+\/)?$/;
const versionPagePath = /^\/release-notes\/version\/firefox-(?<version>[^/]+)\/$/;

// The release notes pages are generated by starlight-changelogs, which sets
// no description, so add the meta tags a docs page gets from its frontmatter.
function setDescription(starlightRoute: StarlightRouteData, description: string) {
  starlightRoute.entry.data.description = description;
  starlightRoute.head.push(
    { tag: "meta", attrs: { name: "description", content: description } },
    { tag: "meta", attrs: { property: "og:description", content: description } },
  );
}

export const onRequest = defineRouteMiddleware((context) => {
  const { starlightRoute } = context.locals;
  const { pathname } = context.url;

  if (indexPagePath.test(pathname)) {
    setDescription(
      starlightRoute,
      "New policies, policy changes and fixes for enterprise admins in each Firefox and Firefox ESR release.",
    );
    return;
  }

  const version = pathname.match(versionPagePath)?.groups?.version;
  if (!version) return;

  // The `154...latest` comparison pages cover a range of releases, so keep their title.
  if (version.includes("...")) {
    const from = version.split("...")[0];
    setDescription(
      starlightRoute,
      `New policies, policy changes and fixes for enterprise admins from Firefox ${from} to the latest release.`,
    );
    return;
  }

  const title = `Firefox ${version} release notes for enterprise admins`;

  starlightRoute.entry.data.title = title;
  setDescription(
    starlightRoute,
    `New policies, policy changes and fixes for enterprise admins in Firefox ${version} and the matching Firefox ESR release.`,
  );

  for (const tag of starlightRoute.head) {
    if (tag.tag === "title") {
      tag.content = `Firefox ${version} release notes | ${starlightRoute.siteTitle}`;
    } else if (tag.tag === "meta" && tag.attrs?.property === "og:title") {
      tag.attrs.content = title;
    }
  }
});
